const a = $json.body || {};
if (!a.releaseId || !a.eventId || !['HOLD','ROLLBACK'].includes(a.decision)) throw new Error('Invalid alert envelope');
return [{json:{eventId:a.eventId,severity:a.decision === 'ROLLBACK' ? 'critical' : 'warning',
 summary:a.decision + ' | ' + a.releaseId + ' | ' + a.reason,
 candidateAdmission:a.routingConfirmed,revision:a.after && a.after.revision,
 evidenceHash:a.hash,metrics:a.evidence || {},nextAction:a.decision === 'ROLLBACK' ?
 'Inspect Candidate. Traffic is Stable-only only when routingConfirmed says STABLE_ONLY.' :
 'Read the reason. Evidence holds collect samples; safety holds stop Candidate.'}}];
